package android.content; import java.util.*; public class Intent { String action; Map<String,Object> extras=new HashMap<>(); public Intent(Context c,Class<?> type){} public Intent setAction(String a){action=a;return this;} public String getAction(){return action;} public Intent putExtra(String k,long v){extras.put(k,v);return this;} public Intent putExtra(String k,String v){extras.put(k,v);return this;} public Intent putExtra(String k,boolean v){extras.put(k,v);return this;} public long getLongExtra(String k,long d){return (long)extras.getOrDefault(k,d);} public String getStringExtra(String k){return (String)extras.get(k);} }
